def natural_address(text):
    """Remove generated gender placeholders without changing sizes or prices."""
    replacements = {
        "تدلل/ين": "تدلل", "تفضل/ي": "تفضل", "تفضّل/ي": "تفضل",
        "تحب/ين": "تحب", "تبحث/ين": "تبحث", "ترغب/ين": "ترغب",
        "تفضل/تفضلي": "تفضل", "تفضّل/تفضلي": "تفضل",
        "حبيبيتي": "حبيبتي",
    }
    for source, target in replacements.items():
        text = re.sub(r"(?<!\w)" + re.escape(source) + r"(?!\w)", target, text)
    return text


_ADDRESS = re.compile(r'(?<!\w)(?:يا\s+)?(?:حبيبتي|عمري|حياتي|روحي|عيني|قلبي|كلبي)(?!\w)')
_WARM_WORDS = ('حبيبتي', 'عمري', 'حياتي', 'يا روحي', 'عيني')


def warm_local_address(text, gender='', history=()):
    """Occasional warmth for factual local replies; never infer gender or facts."""
    if gender != 'female' or not str(text or '').strip():
        return text
    outgoing, incoming = [], []
    for item in history or []:
        if item.get('direction') == 'incoming':
            incoming.append(str(item.get('text') or ''))
        elif item.get('direction') == 'outgoing' or item.get('role') == 'assistant':
            metadata = item.get('raw_payload') or {}
            if isinstance(metadata, str):
                try:
                    metadata = json.loads(metadata)
                except (ValueError, TypeError):
                    metadata = {}
            if not isinstance(metadata, dict) or metadata.get('_delivery_status', 'accepted') == 'accepted':
                outgoing.append(str(item.get('text') or item.get('content') or ''))
    preferences = ' '.join(incoming[-12:])
    if re.search(r'(?<!\w)رسمي[ةه]?(?!\w)|بدون\s+(?:أ?لقاب|دلع)|لا\s*(?:تناديني|تكولين|تقولين|تستخدمين).{0,30}(?:حبيبتي|عمري|حياتي|روحي|أ?لقاب)', preferences):
        return text
    if re.search(r'شكوى|شكوه|إلغاء|الغاء|ألغ|الغ|متضايق|منزعج|ضايج', preferences[-500:]):
        return text
    addresses = list(_ADDRESS.finditer(text))
    if len(addresses) > 1 or any(match[0] != 'عيني' for match in addresses):
        return text
    # Leave a plain conversational turn between affectionate replies.
    if any(_ADDRESS.search(reply) for reply in outgoing[-2:]):
        if addresses:
            match = addresses[0]
            plain = text[:match.start()] + text[match.end():]
            plain = re.sub(r'[ \t]+([،,.؟?])', r'\1', plain)
            return re.sub(r'[ \t]{2,}', ' ', plain).strip(' ،')
        return text
    used = ' '.join(outgoing[-12:])
    chosen = next((word for word in _WARM_WORDS if word not in used), _WARM_WORDS[0])
    if addresses:
        match = addresses[0]
        return text[:match.start()] + chosen + text[match.end():]
    emoji = re.search(r'[🌷🌸💐]', text)
    if emoji:
        return text[:emoji.start()].rstrip() + ' ' + chosen + ' ' + text[emoji.start():]
    return chosen + '، ' + text


def timestamp(value):
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone(timedelta(hours=3)))
    except (ValueError, TypeError):
        return None


def followup_block_reason(db, sender_id, now):
    """One follow-up per unanswered customer turn, never after booking or opt-out."""
    incoming = db.execute("SELECT id,text,created_at FROM messages WHERE sender_id=? AND direction='incoming' ORDER BY id DESC LIMIT 1", (sender_id,)).fetchone()
    if not incoming:
        return "no_customer_message"
    last_time = timestamp(incoming["created_at"])
    current_time = timestamp(now)
    if not last_time or not current_time or current_time < last_time or current_time-last_time >= timedelta(hours=23):
        return "stale_customer_message"
    # Read the actual incoming turn boundary. A fixed last-N window can drop
    # a refusal in its first bubble when the customer sends many short parts.
    columns = {column[1] for column in db.execute('PRAGMA table_info(messages)')}
    visible = ' AND ' + VISIBLE_SQL if 'raw_payload' in columns else ''
    boundary = db.execute("SELECT MAX(id) FROM messages WHERE sender_id=? AND direction='outgoing' AND id<?" + visible,
                          (sender_id, incoming['id'])).fetchone()[0] or 0
    turn = db.execute("SELECT text FROM messages WHERE sender_id=? AND direction='incoming' AND id>? AND id<=? ORDER BY id",
                      (sender_id, boundary, incoming['id'])).fetchall()
    parts = [row['text'] or '' for row in turn]
    latest = db.execute("SELECT direction FROM messages WHERE sender_id=?" + visible + " ORDER BY id DESC LIMIT 1", (sender_id,)).fetchone()
    text = " ".join(parts).strip().replace("أ", "ا").replace("إ", "ا")
    try:
        from .sales_strategy import stop_kind
    except ImportError:
        from sales_strategy import stop_kind
    kind = stop_kind(text)
    if kind in {'opt_out', 'declined'} or re.search(r"اشتريت من", text):
        return "customer_declined_or_deferred"
    if kind == 'deferred' or re.search(r"بعدين|بعدها افكر|راح افكر|خليني افكر|مو هسه|مو هسة", text):
        try:
            from .conversion_growth import reminder_minutes
        except ImportError:
            from conversion_growth import reminder_minutes
        if reminder_minutes(text) is None:
            return "customer_declined_or_deferred"
    if re.fullmatch(r"[\s!؟?.،🌸❤️]*(?:مرحبا|هلو|السلام عليكم|شكرا|مشكور|ممنون|تسلم|تمام)[\s!؟?.،🌸❤️]*", text):
        return "no_open_sales_question"
    if latest and latest["direction"] == "incoming":
        return "customer_waiting_for_answer"
    if db.execute("SELECT 1 FROM orders WHERE sender_id=? LIMIT 1", (sender_id,)).fetchone():
        return "existing_order"
    paused = db.execute("SELECT enabled FROM customer_ai_settings WHERE sender_id=?", (sender_id,)).fetchone()
    if paused and not paused['enabled']:
        return "customer_ai_paused"
    if db.execute("SELECT 1 FROM human_reviews WHERE sender_id=? AND status='pending' AND reason NOT LIKE 'partial_image_match:%' LIMIT 1", (sender_id,)).fetchone():
        return "human_review_pending"
    sent = db.execute("SELECT sent_at,created_at FROM followups WHERE sender_id=? AND status='sent'", (sender_id,)).fetchall()
    if any((timestamp(row['sent_at'] or row['created_at']) or last_time) >= last_time for row in sent):
        return "already_followed_up_without_reply"
    return None
